    document.addEventListener("DOMContentLoaded", function () {
        const tabList = document.querySelector('.tablist');
        const tabItems = document.querySelectorAll('.tablist li');
        const tabPanels = document.querySelectorAll('.tab-panel');
        let selected = null;

        function activateTab(index, updateHash = true) {
		//Remove active state from all tabs
            tabItems.forEach((item) => {
                item.classList.remove('active');
            });
		    // Add active class to the selected tab
		    if (tabItems[index]) {
			    tabItems[index].classList.add('active');
			    selected = index;
                // Update URL hash if requested
                if (updateHash) {
                    const tabId = tabItems[index].id;
                    if (tabId) {
                        history.pushState(null, null, '#' + tabId);
                    }
                }
			    //Pass selected value to handlePanel function
			    handlePanels(selected);
		    }
	    }

	    function handleDropDownItems() {
		    tabItems.forEach((item, index) => {
			    //Onclick of an Li -->
			    item.addEventListener('click', function (e) {
				    // Activate the clicked tab
				    activateTab(index);

				    //Close the Dropdown
				    if (window.innerWidth < 1150) {
					    tabList.classList.toggle('drop-down-active');
				    }
			    });
		    });
	    }

        function handlePanels(selected) {

            const COOKIE_NAME = "cookie_consent_session";
            let button = document.getElementById("scCookieBannerBtn");

            button.onclick = function () {
                // Setting the cookie without Max-Age or Expires makes it a session cookie
                document.cookie = COOKIE_NAME + "=accepted; path=/; SameSite=Lax;";

                // Hide the banner
                document.querySelector('.cookie-banner').style.display = 'none';
            }

            function getCookie(name) {
                const match = document.cookie.match(new RegExp('(^| )' + name + '=([^;]+)'));
                return match ? match[2] : null;
            }

            // If the cookie consent is found, hide the banner
            if (getCookie(COOKIE_NAME)) {
                document.querySelector('.cookie-banner').style.display = 'none';
            }
